starter:
#include <stdio.h>

int main() {
    printf("1時間は %d 秒\n");
    return 0;
}

answer:
#include <stdio.h>

int main() {
    printf("1時間は %d 秒\n", 60 * 60);
    printf("1日は %d 秒\n", 60 * 60 * 24);
    return 0;
}
